 const c=+(item.calories||0); const name=(item.name||'').toLowerCase(); const savory=/chicken|steak|egg|cheese|rice|pasta|sandwich|pizza|burrito|omelet/.test(name); const protein=savory?c*.22/4:c*.10/4; const fat=savory?c*.30/9:c*.28/9; const carbs=Math.max(0,(c-protein*4-fat*9)/4); const fiber=Math.max(1,Math.min(9,carbs*.07));
