function logCard(x){const drink=x.drink?`<span class="log-extra">🥤 DRINK · ${esc(x.drink.name)}${x.drink.amount?` · ${esc(x.drink.amount)}`:''}</span>`:'';const movementRange=x.type==='movement'&&x.startTime&&x.endTime?`<span class="log-extra">🕘 ${esc(x.startTime)} → ${esc(x.endTime)}</span>`:'';const duration=x.type==='movement'&&x.minutes?`<span class="log-extra">⏱️ DURATION · ${esc(x.minutes)} MIN</span>`:'';return `<article class="log-card"><strong>${esc(x.name||x.type)}</strong><span>${esc(x.date||'')} · ${esc(x.time||'')} ${x.nutrition?.calories?`· ${x.nutrition.calories} KCAL`:x.burn?`· ${x.burn} KCAL BURN`:''}</span>${drink}${movementRange}${duration}${x.photo?`<img src="${x.photo}" alt="" style="width:100%;height:120px;object-fit:cover;border-radius:14px;margin-top:9px">`:''}</article>`}
function recipeFacts(r){const n=estimatedNutrition(r);return [`${r.name} lands around ${n.calories} kcal for the saved base serving.`,r.taste||`Expect a cozy ${/chocolate/i.test(r.name)?'chocolate-forward':'soft, comforting'} vibe with room for variations.`,n.estimated?'Some older macro details were not preserved, so this card clearly marks its macro split as an automatic estimate.':'This recipe has preserved macro information in the archive.']}
