 function renderBowl(){qs('#labIngredients').innerHTML=bowl.length?bowl.map((p,i)=>`<div class="ingredient-line"><div><strong>${esc(p.name)}</strong><div class="card-meta">${esc(p.unit)}</div></div><input type="number" min="0" step="0.25" value="${p.qty}" data-lab-qty="${i}"><button class="dialog-close" style="position:static;float:none;margin:0;width:34px;height:34px;font-size:18px" data-lab-remove="${i}">×</button></div>`).join(''):'<div class="empty-state">THE BOWL IS EMPTY. CLICK PANTRY TILES.</div>';qsa('[data-lab-qty]').forEach(i=>i.oninput=()=>{bowl[+i.dataset.labQty].qty=Math.max(0,+i.value||0);renderLabMacros()});qsa('[data-lab-remove]').forEach(b=>b.onclick=()=>{bowl.splice(+b.dataset.labRemove,1);renderBowl()});renderLabMacros()}
 function renderLabMacros(){const t={calories:0,carbs:0,protein:0,fat:0,fiber:0};bowl.forEach(p=>Object.keys(t).forEach(k=>t[k]+=+(p[k]||0)*p.qty));qs('#labMacros').innerHTML=bar('CARBS',t.carbs,100,'carbs')+bar('PROTEIN',t.protein,50,'protein')+bar('FAT',t.fat,45,'fat')+bar('FIBER',t.fiber,25,'fiber')+bar('CALORIES',t.calories,800,'')}
