 const unitIngredient=qs('#unitIngredient');if(unitIngredient){unitIngredient.innerHTML=(D.PANTRY||[]).map((p,i)=>`<option value="${i}">${esc(p.name)} · BASE ${esc(p.unit)}</option>`).join('');const conv=(p,target)=>{const u=String(p.unit).toUpperCase();if(u==='TSP'){if(target==='TSP')return 1;if(target==='TBSP')return 3;if(target==='CUP')return 48}if(u==='TBSP'){if(target==='TSP')return 1/3;if(target==='TBSP')return 1;if(target==='CUP')return 16}if(u==='1/4 CUP'){if(target==='TSP')return 1/12;if(target==='TBSP')return 1/4;if(target==='CUP')return 4}if(u==='CUP'){if(target==='TSP')return 1/48;if(target==='TBSP')return 1/16;if(target==='CUP')return 1}return null};const updateUnit=()=>{const p=D.PANTRY[+unitIngredient.value],target=qs('#unitType').value,q=+qs('#unitQty').value,baseCount=conv(p,target);qs('#unitQtyLabel').textContent=`${q} ${target}`;if(baseCount==null){qs('#unitNutrition').innerHTML=`<div class="selected-food"><strong>${esc(p.name)}</strong><p>THIS ITEM'S SAVED BASE UNIT IS ${esc(p.unit)}, SO A RELIABLE ${target} CONVERSION IS NOT AVAILABLE.</p></div>`;return}const n=scaledNutrition(p,baseCount*q);qs('#unitNutrition').innerHTML=miniMacros(n)};unitIngredient.onchange=updateUnit;qs('#unitType').onchange=updateUnit;qs('#unitQty').oninput=updateUnit;updateUnit();}
